"use client";

import React, { useRef, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Activity, ArrowRight, BriefcaseBusiness, CalendarDays, Check, CheckCircle2, Clock3, Cloud, Code2, Download, Eye, FileText, Folder, GraduationCap, ImageIcon, Layers, LockKeyhole, Mail, MessageSquare, Pencil, Plus, Search, Upload, Users, X } from "lucide-react";
import { PageHeader, Panel, Button, Badge, Field, Input, Select, Switch, Tabs, DataTable, SearchInput, Progress, Stat, Modal, useLocalState } from "@/components/admin/ui";
import { useAdmin } from "@/components/admin/store";
import { CompanyLogo, COMPANY_LOGO_SRC } from "./company-logo";
import styles from "./content-pages.module.css";
import contentFixtures from "@/data/admin/content.json";
