const reference = contentFixtures.reference;
function seed(key) {
  if (Object.prototype.hasOwnProperty.call(contentFixtures.datasets, key)) return contentFixtures.datasets[key];
  const prefix = Object.keys(contentFixtures.templates).sort((a,b) => b.length-a.length).find((entry) => key.startsWith(entry));
  return prefix ? contentFixtures.templates[prefix] : null;
}
function commit(command, notify, type, payload, success) {
  const result = command(type, payload);
  if (!result.ok) { notify(result.error || "The action could not be completed."); return result; }
  if (success) notify(success);
  return result;
}
const allProjectTasks = (db) => Object.entries(db.datasets).filter(([key]) => key.startsWith("olentra-admin-project-tasks-")).flatMap(([key, rows]) => Array.isArray(rows) ? rows.map((row) => ({ ...row, projectId: row.projectId || key.replace("olentra-admin-project-tasks-", "") })) : []);
const internTasks = (db, id) => allProjectTasks(db).filter((row) => (row.internId || row.intern) === id);
const progressFor = (tasks) => tasks.length ? Math.round(tasks.filter((row) => row.status === "Approved").length / tasks.length * 100) : 0;

const CONTENT_KEY = "olentra-admin-content-v1";
const APPLICATION_KEY = "olentra-admin-applications-v1";
const ENQUIRY_KEY = "olentra-admin-enquiries-v1";
const stages = reference.stages;
const toneFor = (value) => /^(not issued|inactive)$/i.test(value) ? "muted" : /published|active|approved|issued|resolved|joined|open|completed/i.test(value) ? "success" : /review|awaiting|offer/i.test(value) ? "warning" : /declined|revoked|spam/i.test(value) ? "danger" : /draft|hidden|closed|onboarding/i.test(value) ? "muted" : "blue";
const Status = ({ value }) => <Badge tone={toneFor(value)}>{value}</Badge>;
const contains = (row, query) => JSON.stringify(row).toLowerCase().includes(query.toLowerCase());
const updateById = (rows, id, changes) => rows.map((row) => row.id === id ? { ...row, ...changes } : row);
const Textarea = (props) => <textarea className={styles.textarea} {...props} />;
const Empty = ({ children }) => <div className={styles.empty}><Search size={24} /><p>{children || "No matching records. Try another search or filter."}</p></div>;
const Info = ({ label, children }) => <div className={styles.info}><span className="workspace-muted">{label}</span><strong>{children}</strong></div>;
function Missing({title,href}) { return <><PageHeader title={`${title} not found`} description="This record does not exist in the shared directory." /><Button href={href}>Return to directory</Button></>; }
function download(name, text, type = "text/plain;charset=utf-8") { const href = URL.createObjectURL(new Blob([text], { type })); const a = document.createElement("a"); a.href = href; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(href), 1000); }
function exportRows(name, rows) { const keys = Object.keys(rows[0] || {}); const quote = (value) => `"${String(value ?? "").replaceAll('"', '""')}"`; download(name, [keys.map(quote).join(","), ...rows.map((row) => keys.map((key) => quote(row[key])).join(","))].join("\n"), "text/csv;charset=utf-8"); }
function CreationModal({ open, onClose, title, label = "Title", onCreate }) { const [value, setValue] = useState(""); return <Modal open={open} onClose={onClose} title={title}><form className="workspace-stack" onSubmit={(event) => { event.preventDefault(); if (!value.trim()) return; const result = onCreate(value.trim()); if (result === false) return; setValue(""); onClose(); }}><Field label={label}><Input required value={value} onChange={(event) => setValue(event.target.value)} autoFocus /></Field><p className="workspace-muted workspace-small">This creates a local demo record in this browser.</p><div className="workspace-row"><Button type="button" onClick={onClose}>Cancel</Button><Button type="submit" variant="primary">Create</Button></div></form></Modal>; }
function DocumentModal({ title, open, onClose }) { return <Modal open={open} onClose={onClose} title={title}><div className={styles.document}><FileText size={42} /><h3>{title}</h3><p>Illustrative document preview</p><p>This local demo shows the document workflow. No private applicant or customer files are connected.</p><Button onClick={() => download(`${(title || "sample-document").replace(/\.[^.]+$/, "")}-sample.txt`, reference.documentPreview) } icon={Download}>Download sample</Button></div></Modal>; }

export function ContentLibraryPage() {
  const { notify, command, db } = useAdmin(); const router = useRouter(); const [rows, setRows] = useLocalState(CONTENT_KEY, seed(CONTENT_KEY)); const [tab, setTab] = useState("Pages"); const [query, setQuery] = useState(""); const [status, setStatus] = useState("All"); const [create, setCreate] = useState(false);
  const visible = rows.filter((row) => contains(row, query) && (status === "All" || row.status === status) && (tab !== "Articles" || row.type === "Article") && (tab !== "Reusable blocks" || row.type === "Block"));
  return <><PageHeader title="Content library" description="Manage pages, articles and reusable website content." actions={<><Button href="/" icon={Eye}>Preview website</Button><Button variant="primary" icon={Plus} onClick={() => setCreate(true)}>Create content</Button></>} /><Tabs items={["Pages", "Articles", "Media", "Reusable blocks"]} value={tab} onChange={(value) => value === "Media" ? router.push("/dashboard/content/media") : setTab(value)} /><div className={styles.asideLayout}><div className="workspace-stack"><div className="workspace-grid workspace-grid-3"><Stat label="Published" value={rows.filter((x) => x.status === "Published").length} icon={FileText} /><Stat label="Drafts" value={rows.filter((x) => x.status === "Draft").length} icon={Pencil} /><Stat label="Awaiting review" value={rows.filter((x) => x.status === "In review").length} icon={Clock3} /></div><Panel><div className="workspace-toolbar"><SearchInput value={query} onChange={setQuery} placeholder="Search content by title…" /><Select aria-label="Content status" options={["All", "Published", "Draft", "In review", "Hidden"]} value={status} onChange={(e) => setStatus(e.target.value)} /><Select aria-label="Locale" options={["EN"]} /></div><DataTable columns={[{ key: "title", label: "Title", render: (v, row) => <Link className="workspace-link" href={`/dashboard/content/pages/${row.id}/edit`}><FileText size={16} />{v}</Link> }, { key: "type", label: "Type" }, { key: "status", label: "Status", render: (v) => <Status value={v} /> }, { key: "locale", label: "Locale" }, { key: "updated", label: "Updated" }, { key: "id", label: "Actions", render: (v) => <Button href={`/dashboard/content/pages/${v}/edit`} variant="ghost" icon={Pencil}>Edit</Button> }]} rows={visible} /></Panel></div><div className="workspace-stack"><Panel title="Publishing checklist"><div className="workspace-check-list">{reference.publishingChecklist.map((item, i) => <div className="workspace-list-row" key={item.title}><CheckCircle2 size={20} color={i === 2 ? "#fbbf24" : "#16d99a"} /><div><strong>{item.title}</strong><p className="workspace-small workspace-muted">{item.detail}</p></div></div>)}</div></Panel><Panel title="Scheduled content"><Badge tone="blue">Upcoming article</Badge><h3>{reference.scheduledContent.title}</h3><p className="workspace-muted">{reference.scheduledContent.date}</p><Button href="/dashboard/content/pages/company-insights/edit" variant="ghost">Review scheduled article <ArrowRight size={16} /></Button></Panel><Panel title="Draft → Review → Publish"><p className="workspace-muted">Create content, request a review, then publish approved changes.</p><Button href="/dashboard/approvals">View approval queue</Button></Panel></div></div><CreationModal title="Create content" open={create} onClose={() => setCreate(false)} onCreate={(title) => { const id = `content-${Date.now()}`; const result = setRows((current) => [...current, { ...reference.newContent, id, title, type: tab === "Articles" ? "Article" : tab === "Reusable blocks" ? "Block" : "Page" }]); if (!result.ok) { notify(result.error); return false; } notify("Content draft created locally."); router.push(`/dashboard/content/pages/${id}/edit`); return true; }} /></>;
}

const blockNames = reference.blocks;
export function PageEditorPage({ pageId = "homepage" }) {
  const { notify, command, db } = useAdmin(); const [rows, setRows] = useLocalState(CONTENT_KEY, seed(CONTENT_KEY)); const page = rows.find((row) => row.id === pageId); const [block, setBlock] = useState("Hero"); const [model, setModel] = useLocalState(`olentra-admin-page-${pageId}`, seed(`olentra-admin-page-${pageId}`)); const [preview, setPreview] = useState(false); const [history, setHistory] = useState(false);
  if (!page) return <Missing title="Page" href="/dashboard/content" />;
  const versions = db.datasets[`olentra-admin-page-history-${pageId}`] || [];
  const active = block === "Hero" ? model : { ...reference.blockDefaults[block], ...model.blocks?.[block] }; const change = (key, value) => setModel(block === "Hero" ? { ...model, [key]: value } : { ...model, blocks: { ...model.blocks, [block]: { ...active, [key]: value } } });
  const save = (status) => commit(command, notify, "content.save", { id: pageId, model, status }, status === "In review" ? "Page submitted for review." : "Page draft saved.");
  const visitor = <div className={styles.visitor}><div className={styles.visitorNav}><CompanyLogo className="workspace-preview-company-logo" /><span>Services　 Products　 About</span></div><div className={styles.visitorHero}><Badge tone="blue">{block}</Badge><h2>{active.title}</h2><p>{active.description}</p><Button href={model.destination} variant="primary">{model.button}</Button></div><div className={styles.previewTiles}>{[Layers, Cloud, Code2].map((Icon, i) => <div key={i}><Icon /><div className={styles.skeleton} /><div className={styles.skeleton} /></div>)}</div></div>;
  return <><PageHeader eyebrow="Content & Media / Pages" title={`Edit ${page.title.toLowerCase()}`} description="Update content, media and section settings for this page." actions={<><Button onClick={() => save("Draft")}>Save draft</Button><Button onClick={() => setPreview(true)} icon={Eye}>Preview</Button><Button variant="primary" onClick={() => save("In review")}>Request review</Button></>} /><div className={styles.statusStrip}><span>Status: <Status value={page.status} /></span><span>Locale: English</span></div><div className={styles.editorLayout}><Panel title="Page sections" description="Manage and reorder page content.">{blockNames.map((name) => <button className={`${styles.blockButton} ${name === block ? styles.selected : ""}`} onClick={() => setBlock(name)} key={name}><Layers size={18} />{name}</button>)}</Panel><Panel title={`Edit section: ${block}`} description="Update the content and media for this section."><div className="workspace-stack"><Field label="Section title"><Input value={active.title} onChange={(e) => change("title", e.target.value)} /></Field><Field label="Description"><div className={styles.richToolbar}>Paragraph　 |　 <b>B</b>　<i>I</i>　<u>U</u>　 • List</div><Textarea rows={5} value={active.description} onChange={(e) => change("description", e.target.value)} /></Field><div className="workspace-grid workspace-grid-2"><Field label="Primary button label"><Input value={model.button} onChange={(e) => setModel({ ...model, button: e.target.value })} /></Field><Field label="Button destination"><Input value={model.destination} onChange={(e) => setModel({ ...model, destination: e.target.value })} /></Field></div><Field label="Hero image"><Link className={styles.assetRow} href="/dashboard/content/media"><div className={styles.smallArt} /><div>{reference.heroAsset.title}<p className="workspace-muted workspace-small">{reference.heroAsset.dimensions} · {reference.heroAsset.size}</p></div><Pencil size={17} /></Link></Field></div></Panel><div className="workspace-stack"><Panel title="Visitor preview" description="How this section looks on the public website.">{visitor}</Panel><Panel title="Page settings"><div className="workspace-stack"><Field label="Slug"><Input readOnly value={pageId === "homepage" ? "/" : `/${pageId}`} /></Field><Field label="SEO title"><Input value={model.seo} onChange={(e) => setModel({ ...model, seo: e.target.value })} /></Field><Field label="Visibility"><Select options={["Public", "Hidden", "Draft"]} value={model.visibility} onChange={(e) => setModel({ ...model, visibility: e.target.value })} /></Field><Button variant="ghost" onClick={() => setHistory(true)}>View version history</Button></div></Panel></div></div><Modal open={preview} onClose={() => setPreview(false)} title="Visitor experience preview">{visitor}</Modal><Modal open={history} onClose={() => setHistory(false)} title="Version history"><div className="workspace-list">{versions.map((version) => <div key={version.id} className={styles.revision}><strong>{version.status} · {version.actor}</strong><p>{version.date}</p><Button onClick={() => { const result = commit(command, notify, "content.restore", { id: pageId, versionId: version.id }, "Content revision restored as a draft."); if (result.ok) setHistory(false); }}>Restore this version</Button></div>)}{!versions.length && <p className="workspace-muted">No saved revisions yet.</p>}</div></Modal></>;
}

function AssetArt({ asset, large }) { return asset.src ? <img className={large ? styles.largeArt : styles.mediaArt} src={asset.src} alt={asset.alt || asset.title} /> : <div className={`${large ? styles.largeArt : styles.mediaArt} ${styles[asset.art] || styles.wave}`}>{asset.art === "brand" ? <CompanyLogo src={COMPANY_LOGO_SRC} companyName="Olentra Technologies" className="workspace-media-company-logo" /> : asset.art === "document" ? <FileText size={64} /> : asset.art === "cloud" ? <Cloud size={86} /> : <div className={styles.waveLine} />}</div>; }
export function MediaLibraryPage() {
  const { notify, command, db } = useAdmin(); const [assets, setAssets] = useLocalState("olentra-admin-media-v1", seed("olentra-admin-media-v1")); const [query, setQuery] = useState(""); const [tab, setTab] = useState("All assets"); const [selected, setSelected] = useState("hero"); const [folder, setFolder] = useState(false); const [folders, setFolders] = useLocalState("olentra-admin-media-folders", seed("olentra-admin-media-folders")); const [activeFolder, setActiveFolder] = useState(""); const upload = useRef(null); const asset = assets.find((x) => x.id === selected) || assets[0];
  const filtered = assets.filter((x) => contains(x, query) && (tab === "All assets" || x.type === tab) && (!activeFolder || x.folder === activeFolder || (activeFolder === "Website" && reference.mediaFolderAssets.Website.includes(x.id)) || (activeFolder === "Branding" && x.id === "brand") || (activeFolder === "Products" && x.id === "product")));
  const uploadFile = (e) => { const file = e.target.files?.[0]; if (!file) return; if (file.size > 3 * 1024 * 1024) return notify("Choose an image smaller than 3 MB for this browser demo."); const reader = new FileReader(); reader.onload = () => { const id = `asset-${Date.now()}`; const result = setAssets((current) => [...current, { ...reference.newAsset, id, title: file.name, size: `${Math.round(file.size / 1024)} KB`, src: reader.result, folder: activeFolder || reference.newAsset.folder }]); if (upload.current) upload.current.value = ""; if (!result.ok) { notify(result.error); return; } setSelected(id); notify("Image uploaded to this browser’s local media library."); }; reader.readAsDataURL(file); };
  return <><PageHeader title="Media library" description="Organize website images, files and accessibility details." actions={<><Button icon={Folder} onClick={() => setFolder(true)}>Create folder</Button><Button icon={Upload} variant="primary" onClick={() => upload.current?.click()}>Upload assets</Button></>} /><input ref={upload} type="file" accept="image/*" onChange={uploadFile} hidden /><Tabs items={["All assets", "Images", "Documents", "Videos"]} value={tab} onChange={setTab} /><div className={styles.mediaLayout}><div className="workspace-stack"><div className="workspace-toolbar"><SearchInput value={query} onChange={setQuery} placeholder="Search assets by name or type…" />{folders.map((name) => <Button key={name} variant={activeFolder === name ? "primary" : "default"} icon={Folder} onClick={() => setActiveFolder(activeFolder === name ? "" : name)}>{name}</Button>)}</div><div className={styles.mediaGrid}>{filtered.map((item) => <button onClick={() => setSelected(item.id)} className={`${styles.mediaCard} ${selected === item.id ? styles.selected : ""}`} key={item.id}><AssetArt asset={item} /><strong>{item.title}</strong><span className="workspace-muted workspace-small">{item.type === "Documents" ? "PDF" : "IMAGE"} · {item.size}</span>{item.type === "Images" && !item.alt && <Badge tone="warning">Alt text missing</Badge>}</button>)}</div>{!filtered.length && <Empty>{tab === "Videos" ? "No videos have been added to this library." : undefined}</Empty>}<p className="workspace-muted workspace-small">Showing {filtered.length} of {assets.length} assets</p></div>{asset && <Panel><AssetArt asset={asset} large /><h2>{asset.title}</h2><Info label="Format">{asset.type === "Documents" ? "PDF" : "IMAGE"}</Info><Info label="Size">{asset.size}</Info><Field label="Alt text"><Textarea value={asset.alt} onChange={(e) => setAssets(updateById(assets, asset.id, { alt: e.target.value }))} rows={3} /></Field><Info label="Usage">{asset.usage}</Info><div className="workspace-row"><Button onClick={() => commit(command, notify, "media.update", { id: asset.id, patch: { alt: asset.alt } }, "Accessibility details saved.")} variant="primary">Save details</Button><Button icon={Download} onClick={() => { if (asset.src) { const a = document.createElement("a"); a.href = asset.src; a.download = asset.title; a.click(); } else download(`${asset.id}-asset-details.txt`, `${asset.title}\nAlt text: ${asset.alt}\nUsage: ${asset.usage}`); }}>Download</Button></div></Panel>}</div><CreationModal open={folder} onClose={() => setFolder(false)} title="Create media folder" label="Folder name" onCreate={(value) => { if (folders.some((folder) => folder.toLowerCase() === value.toLowerCase())) { notify("A folder with this name already exists."); return false; } const result = setFolders((current) => [...current, value]); if (!result.ok) { notify(result.error); return false; } setActiveFolder(value); notify("Media folder created locally."); return true; }} /></>;
}

function CareersTabs({ value }) { return <div className="workspace-toolbar">{reference.careersLinks.map(({title, href}) => <Button key={title} href={href} variant={value === title ? "primary" : "ghost"}>{title}</Button>)}</div>; }
export function CareersPage() {
  const { notify, command, db, features, updateFeature, featureSaving = false, featureError = "", environment } = useAdmin(); const router = useRouter(); const [rows, setRows] = useLocalState("olentra-admin-opportunities", seed("olentra-admin-opportunities")); const controls = { visible: features.internships, applications: features.applications, portal: features.portal }; const [filter, setFilter] = useState("All types"); const [create, setCreate] = useState(false);
  const [controlPending, setControlPending] = useState(false);
  const [controlError, setControlError] = useState("");
  const controlRequest = useRef(false);
  React.useEffect(() => { setControlError(""); }, [features, environment]);
  const applications = db.datasets[APPLICATION_KEY] || []; const interns = db.datasets["olentra-admin-interns"] || [];
  const opportunityRows = rows.map((row) => ({ ...row, applications: applications.filter((app) => app.programId === row.id).length, interns: interns.filter((intern) => intern.programId === row.id && intern.status === "Active").length }));
  const toggle = async (key, checked) => {
    if (controlRequest.current || featureSaving) return;
    controlRequest.current = true;
    setControlPending(true);
    setControlError("");
    try {
      const result = await updateFeature({ visible: "internships", applications: "applications", portal: "portal" }[key], checked);
      if (result?.ok) notify(environment === "Production" ? "Website setting saved immediately." : "Staging preview setting saved.");
      else { const message = result?.error || "The website setting could not be saved."; setControlError(message); notify(message); }
    } catch (error) { const message = error?.message || "The website setting could not be saved."; setControlError(message); notify(message); }
    finally { controlRequest.current = false; setControlPending(false); }
  };
  return <><PageHeader title="Careers & internships" description="Manage opportunities, intake and active programs." actions={<><Button href="/dashboard/careers/programs/frontend/edit">Program settings</Button><Button variant="primary" icon={Plus} onClick={() => setCreate(true)}>Create opportunity</Button></>} /><CareersTabs value="Opportunities" /><div className="workspace-grid workspace-grid-4"><Stat label="Open opportunities" value={opportunityRows.filter((x) => x.status === "Open").length} icon={BriefcaseBusiness} /><Stat label="Applications" value={applications.length} icon={Users} /><Stat label="Active interns" value={interns.filter((row) => row.status === "Active").length} icon={GraduationCap} /><Stat label="Awaiting review" value={applications.filter((row) => row.stage === "Screening").length} icon={FileText} /></div><div className={styles.asideLayout}><Panel title="Opportunities" description="All career and internship opportunities." actions={<Select aria-label="Opportunity type" options={["All types", "Internship", "Full time"]} value={filter} onChange={(e) => setFilter(e.target.value)} />}><DataTable columns={[{ key: "title", label: "Opportunity", render: (v, row) => <Link className="workspace-link" href={`/dashboard/careers/programs/${row.id}/edit`}>{v}</Link> }, { key: "type", label: "Type" }, { key: "status", label: "Intake status", render: (v) => <Status value={v} /> }, { key: "applications", label: "Applications" }, { key: "interns", label: "Active interns" }, { key: "closing", label: "Closing date" }]} rows={opportunityRows.filter((x) => filter === "All types" || x.type === filter)} /><p className={styles.footerNote}>Individual opportunity intake is subject to the program-wide controls.</p></Panel><div className="workspace-stack"><Panel title="Internship program controls" description={environment === "Production" ? "Global switches update the website immediately." : "Staging preview controls only."}>{(featureSaving || controlPending) && <p className="workspace-small workspace-muted" role="status">Saving website setting…</p>}{(controlError || featureError) && <div className="workspace-note" role="alert">{controlError || featureError}</div>}<div className={styles.switchBlock}><Switch label="Public visibility" description="Show internship programs on the website" checked={controls.visible} disabled={featureSaving || controlPending} onChange={(value) => toggle("visible", value)} /></div><div className={styles.switchBlock}><Switch label="New applications" description={features.internships && features.applications && !features.maintenance ? "New internship applications are open" : "New internship applications are closed"} checked={controls.applications} disabled={featureSaving || controlPending} onChange={(value) => toggle("applications", value)} /></div><div className={styles.switchBlock}><Switch label="Existing intern portal" description="Allow current interns to access their portal" checked={controls.portal} disabled={featureSaving || controlPending} onChange={(value) => toggle("portal", value)} /></div></Panel><Panel title="Program progress" description="Internship lifecycle across all programs.">{reference.internStatuses.map((label) => ({ label, value: interns.filter((row) => row.status === label).length, progress: interns.length ? interns.filter((row) => row.status === label).length / interns.length * 100 : 0 })).map(({label, value, progress}) => <div className="workspace-stack" key={label}><Info label={label}>{value}</Info><Progress value={progress} /></div>)}</Panel></div></div><CreationModal title="Create opportunity" open={create} onClose={() => setCreate(false)} onCreate={(title) => { const id = `program-${Date.now()}`; const result = setRows((current) => [...current, { ...reference.newOpportunity, id, title }]); if (!result.ok) { notify(result.error); return false; } notify("Opportunity draft created locally."); router.push(`/dashboard/careers/programs/${id}/edit`); return true; }} /></>;
}

export function ApplicationsPage() {
  const { notify, command, db } = useAdmin(); const [rows, setRows] = useLocalState(APPLICATION_KEY, seed(APPLICATION_KEY)); const [tab, setTab] = useState("Pipeline"); const [query, setQuery] = useState(""); const [track, setTrack] = useState("All programs"); const [create, setCreate] = useState(false); const [newProgramId, setNewProgramId] = useState(""); const programs = db.datasets["olentra-admin-opportunities"] || []; const selectedProgramId = newProgramId || programs[0]?.id || ""; const visible = rows.filter((row) => contains(row, query) && (track === "All programs" || row.track === track));
  return <><PageHeader title="Applications" description="Review applicants and manage the recruitment pipeline." actions={<><Button icon={Download} onClick={() => exportRows("applications.csv", visible)}>Export</Button><Button variant="primary" icon={Plus} onClick={() => setCreate(true)}>Add applicant</Button></>} /><Tabs items={["Pipeline", "List", "Analytics"]} value={tab} onChange={setTab} /><div className="workspace-toolbar"><SearchInput value={query} onChange={setQuery} placeholder="Search applicants by ID or track…" /><Select aria-label="Program" options={["All programs", ...new Set(rows.map((x) => x.track))]} value={track} onChange={(e) => setTrack(e.target.value)} /></div><div className="workspace-grid workspace-grid-4">{[["Applications", rows.length, Users], ["In review", rows.filter((x) => x.stage === "Screening").length, Clock3], ["Offers sent", rows.filter((x) => x.stage === "Offer").length, Mail], ["Joined", rows.filter((x) => x.stage === "Joined").length, CheckCircle2]].map(([label, value, Icon]) => <Stat key={label} label={label} value={value} icon={Icon} />)}</div>{tab === "Pipeline" ? <div className={styles.boardWrapper}><div className={styles.kanban}>{stages.slice(0, 5).map((stage) => <section className={styles.kanbanColumn} key={stage}><div className={styles.kanbanHeading}><h3>{stage}</h3><span className={styles.counterPill}>{visible.filter((x) => x.stage === stage).length}</span></div>{visible.filter((x) => x.stage === stage).map((row) => <Link href={`/dashboard/careers/applications/${row.id}`} className={styles.applicantCard} key={row.id}><strong>Applicant {row.id}</strong><p>{row.track}</p><Badge tone={toneFor(stage)}>{stage === "New" ? "Resume received" : stage}</Badge><small><CalendarDays size={12} /> Submitted: {row.date}</small><small>R　{row.owner}</small></Link>)}</section>)}</div></div> : tab === "List" ? <Panel title="Applicant directory"><DataTable columns={[{ key: "id", label: "Applicant", render: (v) => <Link className="workspace-link" href={`/dashboard/careers/applications/${v}`}>Applicant {v}</Link> }, { key: "track", label: "Program" }, { key: "stage", label: "Stage", render: (v) => <Status value={v} /> }, { key: "owner", label: "Reviewer" }, { key: "date", label: "Submitted" }]} rows={visible} /></Panel> : <Panel title="Recruitment funnel" description="Counts reflect the local sample directory.">{stages.map((stage) => <div key={stage} className="workspace-stack"><Info label={stage}>{visible.filter((x) => x.stage === stage).length}</Info><Progress value={visible.length ? visible.filter((x) => x.stage === stage).length / visible.length * 100 : 0} /></div>)}</Panel>}<p className={styles.applicationNotice}><LockKeyhole size={15} />Private recruitment workspace · Only invited reviewers can access applicant details.</p><Modal title="Add applicant" open={create} onClose={() => setCreate(false)}><form className="workspace-stack" onSubmit={(event) => { event.preventDefault(); const program = programs.find((row) => row.id === selectedProgramId); if (!program) { notify("Choose an existing program."); return; } const programModel = db.datasets[`olentra-admin-program-${program.id}`]; const id = String(Math.max(0, ...rows.map((row) => Number(row.id)).filter(Number.isFinite)) + 1).padStart(3, "0"); const date = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }).format(new Date(db.meta.clock)); const result = setRows((current) => [...current, { ...reference.newApplication, id, programId: program.id, track: programModel?.track || program.title, date, activity: [{ id: `activity-${id}-created`, date, at: db.meta.clock, action: "Application received", role: "Recruiter" }] }]); if (!result.ok) { notify(result.error); return; } setCreate(false); notify(`Applicant ${id} added to ${program.title}.`); }}><p className="workspace-muted workspace-small">Create an anonymous sample applicant for an existing program.</p><Field label="Program"><Select required value={selectedProgramId} options={programs.map((program) => ({ value: program.id, label: program.title }))} onChange={(event) => setNewProgramId(event.target.value)} /></Field><div className="workspace-row"><Button type="button" onClick={() => setCreate(false)}>Cancel</Button><Button type="submit" variant="primary" disabled={!selectedProgramId}>Add applicant</Button></div></form></Modal></>;
}

export function ApplicationReviewPage({ applicationId = "024" }) {
  const { notify, command, db } = useAdmin(); const [rows, setRows] = useLocalState(APPLICATION_KEY, seed(APPLICATION_KEY)); const row = rows.find((x) => x.id === applicationId); const [tab, setTab] = useState("Profile"); const [notes, setNotes] = useLocalState(`olentra-admin-applicant-notes-${applicationId}`, seed(`olentra-admin-applicant-notes-${applicationId}`)); const [note, setNote] = useState(""); const [document, setDocument] = useState(""); const [action, setAction] = useState(""); const [reason, setReason] = useState("");
  const apply = (stage, reason) => commit(command, notify, "application.transition", { id: applicationId, status: stage, reason }, `Applicant ${applicationId} moved to ${stage.toLowerCase()}.`);
  if (!row) return <><PageHeader title="Application not found" description="This applicant is not in the local sample directory." /><Button href="/dashboard/careers/applications">Back to applications</Button></>;
  const stageIndex = stages.indexOf(row.stage); const nextStage = stageIndex >= 0 && stageIndex < stages.indexOf("Joined") ? stages[stageIndex + 1] : null; const terminal = !nextStage; const linkedIntern = (db.datasets["olentra-admin-interns"] || []).find((intern) => intern.applicationId === applicationId); const transitionLabel = nextStage === "Joined" ? "Mark as joined" : nextStage ? `Move to ${nextStage.toLowerCase()}` : ""; const availableStages = terminal ? [row.stage] : [row.stage, nextStage, "Declined"];
  return <><PageHeader eyebrow="Applications / Applicant review" title={`Applicant ${applicationId}`} description="Private recruitment workspace" actions={<>{nextStage && <Button variant="primary" icon={CalendarDays} onClick={() => apply(nextStage)}>{transitionLabel}</Button>}{row.stage === "Offer" && <Button icon={Mail} onClick={() => { setReason(row.offer?.message || ""); setAction("Send offer"); }}>{row.offer?.status === "Sent" ? "View / update offer" : "Prepare offer"}</Button>}{row.stage === "Joined" && linkedIntern && <Button href={`/dashboard/careers/interns/${linkedIntern.id}`}>View intern profile</Button>}</>} /><div className={styles.reviewLayout}><Panel title="Applicant summary"><div className={styles.profileTitle}><span className={styles.profileAvatar}>A</span><div><h3>Applicant {applicationId}</h3><Status value={row.stage} /></div></div><Info label="Program">{row.track} internship</Info><Info label="Submitted">{row.date}</Info><Info label="Location">{row.location}</Info><Info label="Availability">{row.availability}</Info><div className={styles.skills}>{row.skills.map((skill) => <Badge key={skill} tone="muted">{skill}</Badge>)}</div></Panel><div className="workspace-stack"><Tabs items={["Profile", "Documents", "Timeline", "Onboarding"]} value={tab} onChange={setTab} />{tab === "Profile" && <Panel title="Application statement"><p className={styles.introMessage}>{row.statement}</p><h3 className={styles.subHeading}>Qualifications</h3>{row.qualifications.map((text) => <div className="workspace-list-row" key={text}><CheckCircle2 size={17} color="#16d99a" /><span className="workspace-small">{text}</span></div>)}</Panel>}{(tab === "Profile" || tab === "Documents") && <Panel title="Documents">{row.documents.map((document) => <div className="workspace-list-row workspace-between" key={document.title}><span className={styles.fileLabel}><FileText size={20} />{document.title}</span><Button icon={Eye} onClick={() => setDocument(document.title)}>View</Button></div>)}</Panel>}{tab === "Onboarding" && <Panel title="Onboarding readiness"><p className={styles.infoText}>Onboarding becomes available after the applicant accepts an offer.</p>{row.onboarding.map((item) => <Info key={item.label} label={item.label}><Status value={item.status} /></Info>)}{(db.datasets["olentra-admin-interns"] || []).some((intern) => intern.applicationId === applicationId) ? <Button href={`/dashboard/careers/interns/${(db.datasets["olentra-admin-interns"] || []).find((intern) => intern.applicationId === applicationId).id}`}>View linked intern profile</Button> : <p className="workspace-muted workspace-small">An intern profile is created when this application joins the program.</p>}</Panel>}{(tab === "Profile" || tab === "Timeline") && <Panel title="Timeline"><div className={styles.timeline}>{row.activity.map((event, index) => <div key={event.id || index}><CheckCircle2 size={20} /><div><strong>{event.action}</strong><p>{event.date} · {event.role}</p></div></div>)}<div><Activity size={20} /><div><strong>Current stage: {row.stage}</strong><p>Local application record</p></div></div></div></Panel>}</div><div className="workspace-stack"><Panel title="Review decision"><Field label="Assigned reviewer"><Select options={["Recruiter", "Engineering mentor", "Program administrator"]} value={row.owner} onChange={(e) => commit(command, notify, "application.update", { id: applicationId, patch: { owner: e.target.value } }, "Reviewer assignment updated.")} /></Field><Field label="Status"><Select options={availableStages} value={row.stage} disabled={terminal} onChange={(event) => { if (event.target.value === "Declined") setAction("Decline"); else if (event.target.value !== row.stage) apply(event.target.value); }} /></Field><Info label="Next step">{nextStage || (row.stage === "Joined" ? "Intern lifecycle" : "Application closed")}</Info></Panel><Panel title="Internal notes · Staff only"><div className="workspace-stack">{notes.map((text, index) => <div className={styles.notes} key={index}>{typeof text === "string" ? text : text.text}</div>)}<Textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Add an internal note" rows={4} /><Button variant="primary" disabled={!note.trim()} onClick={() => { const result = commit(command, notify, "application.note", { id: applicationId, text: note.trim() }, "Private reviewer note saved."); if (result.ok) setNote(""); }}>Save note</Button></div></Panel></div></div><div className={styles.applicationActions}>{terminal ? <span className="workspace-small workspace-muted">{row.stage === "Joined" ? "Recruitment is complete. Manage ongoing work through the intern profile." : "This recruitment application is closed."}</span> : <><Button onClick={() => setAction("Request information")}>Request information</Button><Button variant="danger" onClick={() => setAction("Decline")}>Decline</Button></>}</div><DocumentModal title={document} open={!!document} onClose={() => setDocument("")} /><Modal title={action} open={!!action} onClose={() => setAction("")}><div className="workspace-stack"><p className="workspace-muted">Prepare a local recruitment action for Applicant {applicationId}. No email is sent.</p><Field label={action === "Decline" ? "Decision note" : "Message / offer details"}><Textarea value={reason} onChange={(e) => setReason(e.target.value)} rows={5} placeholder="Add details for the recruitment record…" /></Field><Button disabled={!reason.trim()} variant={action === "Decline" ? "danger" : "primary"} onClick={() => { const type = action === "Decline" ? "application.transition" : action === "Send offer" ? "application.offer" : "application.message"; const result = commit(command, notify, type, action === "Decline" ? { id: applicationId, status: "Declined", reason } : action === "Send offer" ? { id: applicationId, message: reason } : { id: applicationId, text: reason }, "Recruitment action recorded. No email sent."); if (result.ok) { setAction(""); setReason(""); } }}>Record {action === "Send offer" ? "offer" : "action"}</Button></div></Modal></>;
}

export function InternsProjectsPage() {
  const { db } = useAdmin(); const [tab, setTab] = useState("Interns"); const [query, setQuery] = useState(""); const [interns] = useLocalState("olentra-admin-interns", seed("olentra-admin-interns")); const router = useRouter();
  const projectRecords = db.datasets["olentra-admin-projects"] || []; const tasks = allProjectTasks(db); const pending = tasks.filter((row) => row.status === "In review"); const certificates = db.datasets["olentra-admin-certificates"] || [];
  const projects = <div className="workspace-stack">{projectRecords.map((project) => { const rows = tasks.filter((row) => row.projectId === project.id); return <Panel key={project.id} title={project.title} actions={rows.length ? <Button href={`/dashboard/careers/projects/${project.id}/tasks/${rows[0].id}`} variant="ghost">Open project <ArrowRight size={15} /></Button> : null}><p className="workspace-small workspace-muted">Deadline: {project.due}</p><Info label="Task progress">{rows.filter((row) => row.status === "Approved").length} of {rows.length} tasks</Info><Progress value={progressFor(rows)} /><div className={styles.avatarStack}>{project.internIds.map((id) => <span key={id}>I{id}</span>)}</div></Panel>; })}</div>;
  const submissions = <Panel title="Submissions awaiting review" description="Live task submissions that need review."><DataTable columns={[{key:"title",label:"Task"},{key:"projectId",label:"Project",render:(id) => projectRecords.find((row) => row.id === id)?.title},{key:"submitted",label:"Submitted on"},{key:"actions",label:"Action",render:(_,row) => <Button href={`/dashboard/careers/projects/${row.projectId}/tasks/${row.id}`} variant="primary">Review</Button>}]} rows={pending} /></Panel>;
  return <><PageHeader title="Interns & projects" description="Coordinate active interns, work and completion." actions={<><Button onClick={() => setTab("Submissions")}>Review submissions</Button><Button variant="primary" href="/dashboard/careers/projects/website-refresh/tasks/contact">Open project workspace</Button></>} /><Tabs items={["Interns", "Projects", "Submissions", "Certificates"]} value={tab} onChange={(value) => value === "Certificates" ? router.push("/dashboard/careers/certificates") : setTab(value)} /><div className="workspace-grid workspace-grid-4">{[["Active interns", interns.filter((x) => x.status === "Active").length, Users], ["Active projects", projectRecords.length, Layers], ["Submissions to review", pending.length, FileText], ["Ready for certificate", certificates.filter((row) => row.status === "Ready").length, GraduationCap]].map(([label, value, Icon]) => <Stat key={label} label={label} value={value} icon={Icon} />)}</div>{tab === "Interns" ? <><div className={styles.asideLayout}><Panel title="Intern roster" description="Manage interns, their tracks, projects and progress."><SearchInput value={query} onChange={setQuery} placeholder="Search interns or projects…" /><DataTable columns={[{ key: "id", label: "Intern", render: (v) => <Link className="workspace-link" href={`/dashboard/careers/interns/${v}`}>Intern {v}</Link> }, { key: "track", label: "Track" }, { key: "project", label: "Project" }, { key: "progress", label: "Progress", render: (v) => <div className={styles.tableProgress}><Progress value={v} /><span>{v}%</span></div> }, { key: "status", label: "Status", render: (v) => <Status value={v} /> }]} rows={interns.filter((row) => contains(row, query)).map((row) => ({...row,progress:selectInternProgress(db,row.id).progress}))} /></Panel>{projects}</div><div className="workspace-grid workspace-grid-2">{submissions}<Panel title="Completion workflow" description="Standard flow from submission to certificate."><div className={styles.stepper}>{["Submitted", "Reviewed", "Completed", "Certificate"].map((step) => <span key={step}><CheckCircle2 size={23} />{step}</span>)}</div><Button href="/dashboard/careers/certificates">Manage certificates</Button></Panel></div></> : tab === "Projects" ? projects : submissions}</>;
}

export function EnquiriesPage() {
  const { notify, command, db } = useAdmin(); const [rows, setRows] = useLocalState(ENQUIRY_KEY, seed(ENQUIRY_KEY)); const [tab, setTab] = useState("Inbox"); const [query, setQuery] = useState(""); const [status, setStatus] = useState("All"); const [owner, setOwner] = useState("All"); const [spamFilter, setSpamFilter] = useLocalState("olentra-admin-spam-filter", seed("olentra-admin-spam-filter")); const [formOpen, setFormOpen] = useState(false); const [formSettings, setFormSettings] = useLocalState("olentra-admin-contact-form", seed("olentra-admin-contact-form")); const [selected, setSelected] = useState([]);
  const visible = rows.filter((row) => contains(row, query) && (status === "All" || row.status === status) && (owner === "All" || row.owner === owner) && (tab === "Spam" ? row.status === "Spam" : tab === "Resolved" ? row.status === "Resolved" : tab === "Assigned to me" ? row.owner === "Sales lead" && !["Spam", "Resolved"].includes(row.status) : !["Spam", "Resolved"].includes(row.status)));
  return <><PageHeader title="Forms & enquiries" description="Manage incoming website conversations and follow-up." actions={<><Button icon={Download} onClick={() => exportRows("enquiries.csv", visible)}>Export</Button><Button variant="primary" onClick={() => setFormOpen(true)}>Form settings</Button></>} /><Tabs items={["Inbox", "Assigned to me", "Resolved", "Spam"]} value={tab} onChange={setTab} /><div className="workspace-grid workspace-grid-3"><Stat label="Open enquiries" value={rows.filter((x) => !["Resolved", "Spam"].includes(x.status)).length} icon={MessageSquare} /><Stat label="Unassigned" value={rows.filter((x) => x.owner === "Unassigned").length} icon={Users} /><Stat label="Awaiting reply" value={rows.filter((x) => x.status === "Awaiting reply").length} icon={Clock3} /></div><div className={styles.asideLayout}><Panel><div className="workspace-toolbar"><SearchInput value={query} onChange={setQuery} placeholder="Search enquiries…" /><Select aria-label="Enquiry status" options={["All", "New", "Assigned", "In progress", "Awaiting reply", "Resolved", "Spam"]} value={status} onChange={(e) => setStatus(e.target.value)} /><Select aria-label="Enquiry owner" options={["All", "Unassigned", "Sales lead", "Operations"]} value={owner} onChange={(e) => setOwner(e.target.value)} /></div><DataTable columns={[{ key: "selected", label: "", render: (_, row) => <input aria-label={`Select enquiry ${row.id}`} type="checkbox" checked={selected.includes(row.id)} onChange={(e) => setSelected(e.target.checked ? [...selected, row.id] : selected.filter((x) => x !== row.id))} /> }, { key: "id", label: "Enquiry", render: (v) => <Link className="workspace-link" href={`/dashboard/enquiries/${v}`}>Enquiry {v}</Link> }, { key: "topic", label: "Topic" }, { key: "source", label: "Source" }, { key: "owner", label: "Owner" }, { key: "status", label: "Status", render: (v) => <Status value={v} /> }, { key: "date", label: "Received" }]} rows={visible} /><div className="workspace-row"><Button disabled={!selected.length} onClick={() => { let failed = false; selected.forEach((id) => { const result = commit(command, notify, "enquiry.update", { id, patch: { owner: "Sales lead", status: "Assigned" } }); if (!result.ok) failed = true; }); if (!failed) { notify(`${selected.length} enquiries assigned.`); setSelected([]); } }}>Assign selected to Sales lead</Button><span className="workspace-small workspace-muted">{selected.length} selected</span></div></Panel><div className="workspace-stack"><Panel title="Queue priorities"><div className={styles.queueCount}><Users /><strong>{rows.filter((x) => x.owner === "Unassigned").length}</strong><span>need an owner</span></div><div className={styles.queueCount}><Clock3 /><strong>{rows.filter((x) => x.status === "Awaiting reply").length}</strong><span>awaiting reply</span></div><Button variant="ghost" onClick={() => { setOwner("Unassigned"); setTab("Inbox"); }}>Show unassigned enquiries</Button></Panel><Panel title="Spam management"><Switch checked={spamFilter} onChange={setSpamFilter} label="Automatic filtering" description="Local form configuration" /><Button onClick={() => setTab("Spam")}>Review spam</Button></Panel></div></div><Modal open={formOpen} onClose={() => setFormOpen(false)} title="Website form settings"><div className="workspace-stack"><Switch label="Contact form" description="Display the website enquiry form" checked={formSettings.contact} onChange={(value) => setFormSettings({ ...formSettings, contact: value })} /><Switch label="Partner form" description="Accept partnership enquiries" checked={formSettings.partners} onChange={(value) => setFormSettings({ ...formSettings, partners: value })} /><Button variant="primary" onClick={() => { notify("Form settings saved locally."); setFormOpen(false); }}>Save settings</Button></div></Modal></>;
}

export function EnquiryDetailPage({ enquiryId = "018" }) {
  const { notify, command, db } = useAdmin(); const [rows, setRows] = useLocalState(ENQUIRY_KEY, seed(ENQUIRY_KEY)); const row = rows.find((x) => x.id === enquiryId); const [tab, setTab] = useState("Conversation"); const [draft, setDraft] = useLocalState(`olentra-admin-enquiry-draft-${enquiryId}`, seed(`olentra-admin-enquiry-draft-${enquiryId}`)); const [notes, setNotes] = useLocalState(`olentra-admin-enquiry-notes-${enquiryId}`, seed(`olentra-admin-enquiry-notes-${enquiryId}`)); const [note, setNote] = useState(""); const [attachment, setAttachment] = useState(false); const [followup, setFollowup] = useLocalState(`olentra-admin-enquiry-followup-${enquiryId}`, seed(`olentra-admin-enquiry-followup-${enquiryId}`)); const composer = useRef(null); const replies = db.datasets[`olentra-admin-enquiry-replies-${enquiryId}`] || [];
  const change = (key, value) => commit(command, notify, "enquiry.update", { id: enquiryId, patch: { [key]: value } }, "Enquiry updated.");
  if (!row) return <><PageHeader title="Enquiry not found" description="This enquiry is not in the local sample inbox." /><Button href="/dashboard/enquiries">Back to inbox</Button></>;
  return <><PageHeader eyebrow={`Inbox / Enquiry ${enquiryId}`} title={row.topic} description={<Status value={row.status} />} actions={<><Button icon={Pencil} onClick={() => { setTab("Conversation"); setTimeout(() => composer.current?.focus(), 40); }}>Draft reply</Button><Button variant="primary" icon={Check} onClick={() => { change("status", row.status === "Resolved" ? "In progress" : "Resolved"); }}>{row.status === "Resolved" ? "Reopen" : "Resolve"}</Button></>} /><div className={styles.asideLayout}><div className="workspace-stack"><Panel><div className={styles.profileTitle}><span className={styles.profileAvatar}>P</span><div><h3>{row.prospect}</h3><p>{row.contact}</p></div></div><Info label="Source">{row.source}</Info><p className={styles.message}>{row.message}</p><div className={styles.attachment}><FileText size={22} /><strong>{row.attachment.title}</strong><Button variant="ghost" onClick={() => setAttachment(true)}>View attachment</Button></div></Panel><Tabs items={["Conversation", "Internal notes", "Activity"]} value={tab} onChange={setTab} />{tab === "Conversation" && <Panel>{replies.map((reply,index) => <div className={styles.feed} key={reply.id || index}><strong>Reply · {reply.date || reply.createdAt}</strong><p>{typeof reply === "string" ? reply : reply.text}</p></div>)}<Info label="To">{row.contact}</Info><Info label="Subject">Re: {row.topic}</Info><Textarea ref={composer} value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Write a reply…" rows={7} /><div className={styles.footerActions}><span className="workspace-small workspace-muted">Local conversation · No email sent</span><Button variant="primary" onClick={() => { const result = commit(command, notify, "enquiry.reply", { id: enquiryId, text: draft }, "Reply recorded in the local conversation. No email sent."); if (result.ok) setDraft(""); }}>Record reply</Button></div></Panel>}{tab === "Internal notes" && <Panel title="Internal notes · Staff only"><div className="workspace-stack">{notes.length ? notes.map((note, i) => <div className={styles.notes} key={note.id || i}>{typeof note === "string" ? note : note.text}</div>) : <p className="workspace-muted">No internal notes yet.</p>}<Textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Add a private team note…" /><Button variant="primary" disabled={!note.trim()} onClick={() => { const result = commit(command, notify, "enquiry.note", { id: enquiryId, text: note.trim() }, "Private enquiry note saved."); if (result.ok) setNote(""); }}>Save note</Button></div></Panel>}{tab === "Activity" && <Panel title="Enquiry activity">{row.activity.map((event,index) => <Info key={event.id || index} label={event.date}>{event.action}</Info>)}<Info label="Owner">{row.owner}</Info><Info label="Status">{row.status}</Info>{followup.saved && <Info label="Follow-up">{followup.date} at {followup.time} UTC</Info>}{notes.map((_, i) => <Info label="Local activity" key={i}>Internal note added</Info>)}</Panel>}</div><div className="workspace-stack"><Panel title="Enquiry details"><div className="workspace-stack"><Field label="Owner"><Select options={["Sales lead", "Operations", "Unassigned"]} value={row.owner} onChange={(e) => change("owner", e.target.value)} /></Field><Field label="Status"><Select options={["New", "Assigned", "In progress", "Awaiting reply", "Resolved", "Spam"]} value={row.status} onChange={(e) => change("status", e.target.value)} /></Field><Info label="Priority">{row.priority}</Info><Info label="Service">{row.service}</Info><Info label="Region">{row.region}</Info></div></Panel><Panel title="Follow-up"><div className="workspace-stack"><Field label="Date"><Input type="date" min={reference.today} value={followup.date} onChange={(e) => setFollowup({ ...followup, date: e.target.value, saved: false })} /></Field><Field label="Time (UTC)"><Input type="time" value={followup.time} onChange={(e) => setFollowup({ ...followup, time: e.target.value, saved: false })} /></Field><Button variant="primary" disabled={!followup.date || !followup.time} onClick={() => { const result = commit(command, notify, "enquiry.update", { id: enquiryId, patch: { followup: { ...followup, saved: true } } }, "Follow-up recorded. No external reminder scheduled."); if (result.ok) setFollowup({ ...followup, saved: true }); }}>{followup.saved ? "Follow-up recorded" : "Schedule follow-up"}</Button></div></Panel><Panel title="Internal activity"><Badge tone="muted">Staff only</Badge><Info label="Assigned to">{row.owner}</Info><Info label="Internal notes">{notes.length}</Info></Panel></div></div><DocumentModal title={row.attachment.title} open={attachment} onClose={() => setAttachment(false)} /></>;
}

export function ProjectTaskReviewPage({ projectId = "website-refresh", taskId = "contact" }) {
  const { notify, command, db } = useAdmin(); const router = useRouter(); const [tasks, setTasks] = useLocalState(`olentra-admin-project-tasks-${projectId}`, seed(`olentra-admin-project-tasks-${projectId}`)); const [selectedId, setSelectedId] = useState(taskId); const [filter, setFilter] = useState("All tasks"); const [feedback, setFeedback] = useState(""); const [privateNotes, setPrivateNotes] = useLocalState(`olentra-admin-project-private-${projectId}`, seed(`olentra-admin-project-private-${projectId}`)); const [reviews, setReviews] = useLocalState(`olentra-admin-project-reviews-${projectId}`, seed(`olentra-admin-project-reviews-${projectId}`)); const [error, setError] = useState(""); const [tab, setTab] = useState("Tasks & Reviews"); const [file, setFile] = useState(false); const [create, setCreate] = useState(false); const [submitOpen, setSubmitOpen] = useState(false); const [submissionNotes, setSubmissionNotes] = useState(""); const [workLink, setWorkLink] = useState(""); const [submissionError, setSubmissionError] = useState(""); const task = tasks.find((x) => x.id === selectedId); const projectRecord = (db.datasets["olentra-admin-projects"] || []).find((row) => row.id === projectId);
  if (!projectRecord || !task) return <Missing title="Project task" href="/dashboard/careers/interns" />;
  const review = (status) => { const result = commit(command, notify, "task.review", { projectId, taskId: task.id, decision: status === "Approved" ? "approve" : "changes", feedback }, "Submission review recorded."); if (!result.ok) { setError(result.error); return; } setFeedback(""); setError(""); };
  const taskGroups = reference.taskStatuses;
  return <><PageHeader eyebrow={`Internships / Projects / ${projectRecord.name}`} title={projectRecord.name} description={projectRecord.description} actions={<Button variant="primary" icon={Plus} onClick={() => setCreate(true)}>Add task</Button>} /><Tabs items={["Overview", "Team", "Tasks & Reviews", "Files"]} value={tab} onChange={setTab} /><div className="workspace-grid workspace-grid-4"><Stat label="Project progress" value={`${Math.round(tasks.filter((x) => x.status === "Approved").length / tasks.length * 100)}%`} icon={Activity} /><Stat label="Total tasks" value={tasks.length} icon={FileText} /><Stat label="Approved" value={tasks.filter((x) => x.status === "Approved").length} icon={CheckCircle2} /><Stat label="In review" value={tasks.filter((x) => x.status === "In review").length} icon={Clock3} /></div>{tab === "Overview" ? <div className="workspace-grid workspace-grid-2"><Panel title="Project overview"><Info label="Due date">{projectRecord.due}</Info><Info label="Project type">{projectRecord.type}</Info><Info label="Project owner">{projectRecord.mentor}</Info><p className={styles.infoText}>{projectRecord.description}</p><Button onClick={() => setTab("Tasks & Reviews")}>Open tasks and reviews</Button></Panel><Panel title="Milestones">{projectRecord.milestones.map((item) => <Info label={item.title} key={item.title}><Status value={item.status} /></Info>)}</Panel></div> : tab === "Team" ? <Panel title="Project team"><DataTable columns={[{ key: "id", label: "Intern", render: (v) => <Link className="workspace-link" href={`/dashboard/careers/interns/${v}`}>Intern {v}</Link> }, { key: "role", label: "Role" }, { key: "tasks", label: "Assigned tasks" }]} rows={(db.datasets["olentra-admin-interns"] || []).filter((row) => projectRecord.internIds.includes(row.id)).map((row) => ({ ...row, role: row.track, tasks: tasks.filter((task) => (task.internId || task.intern) === row.id).length }))} /></Panel> : tab === "Files" ? <Panel title="Project files"><div className={styles.attachment}><FileText /><span>{task.file?.title} · Version {task.version}</span><Button icon={Eye} onClick={() => setFile(true)}>Preview</Button></div><p className={styles.footerNote}>Submission attachments are illustrative files in the local prototype.</p></Panel> : <div className={styles.projectTaskLayout}><Panel title="Project tasks" actions={<Select aria-label="Task status" value={filter} options={["All tasks", ...taskGroups]} onChange={(e) => setFilter(e.target.value)} />}>{taskGroups.filter((status) => filter === "All tasks" || filter === status).map((status) => <div key={status}><h3 className={styles.subHeading}>{status} <span className={styles.counterPill}>{tasks.filter((x) => x.status === status).length}</span></h3>{tasks.filter((x) => x.status === status).map((item) => <button key={item.id} className={`${styles.taskButton} ${task.id === item.id ? styles.selected : ""}`} onClick={() => { setSelectedId(item.id); setFeedback(""); setError(""); router.replace(`/dashboard/careers/projects/${projectId}/tasks/${item.id}`, { scroll: false }); }}><span><strong>{item.title}</strong><small>Intern {item.intern} · Due {item.due}</small></span><Status value={item.status} /></button>)}</div>)}</Panel><Panel title={task.title}><div className="workspace-row"><Status value={task.status} /><Badge tone="muted">Work review</Badge>{["To do", "In progress", "Changes requested"].includes(task.status) && <Button icon={Upload} onClick={() => { setSubmissionNotes(""); setWorkLink(""); setSubmissionError(""); setSubmitOpen(true); }}>Record sample submission</Button>}</div><div className={styles.taskContent}><div className="workspace-stack"><Panel title="Submission review"><Info label="Version">v{task.version}</Info><Info label="Submitted">{task.submitted}</Info><Info label="Assigned to"><Link className="workspace-link" href={`/dashboard/careers/interns/${task.intern}`}>Intern {task.intern}</Link></Info><Info label="Task due date">{task.due}</Info><h4>Attached file</h4><div className={styles.filePreview}><strong>{task.title}</strong><span>{task.file?.title}</span><div className={styles.skeleton} /><div className={styles.skeleton} /></div><Button disabled={!task.file} onClick={() => setFile(true)} icon={Eye}>{task.file ? `View ${task.file.title}` : "No attachment submitted"}</Button><Info label="Work link">{task.workLink ? <a className="workspace-link" href={task.workLink} target="_blank" rel="noopener noreferrer">{task.workLink}</a> : "Not provided"}</Info><p className="workspace-small workspace-muted">Submission notes: {task.notes || "No sample submission recorded yet."}</p></Panel><Panel title="Task timeline"><div className={styles.timeline}>{(task.history || []).map((revision, index) => <div key={index}><Clock3 size={18} /><div><strong>v{revision.version} · {revision.status}</strong><p>{revision.date} · {revision.feedback}</p></div></div>)}{reviews.filter((row) => row.taskId ? row.taskId === task.id : row.task === task.title).map((item, i) => <div key={i}><CheckCircle2 size={18} /><div><strong>{item.status}</strong><p>{item.feedback}</p></div></div>)}</div></Panel></div><div className="workspace-stack"><Panel title="Reviewer feedback *" description="Visible to the intern when the review is published."><Textarea rows={7} value={feedback} onChange={(e) => { setFeedback(e.target.value); setError(""); }} maxLength={1000} placeholder="Add feedback on the submission, including what’s good and what needs to change…" /><span className={styles.counter}>{feedback.length} / 1000</span>{error && <p className={styles.error} role="alert">{error}</p>}<div className={styles.actionLine}><Button disabled={!["In review", "Changes requested"].includes(task.status)} onClick={() => review("Changes requested")}>Request changes</Button><Button disabled={!["In review", "Changes requested"].includes(task.status)} variant="primary" onClick={() => review("Approved")}>Approve submission</Button></div></Panel><Panel title="Internal notes (private)" description="Only visible to the company team, not to the intern."><Textarea rows={5} value={privateNotes} onChange={(e) => setPrivateNotes(e.target.value)} placeholder="Add internal notes, quality observations or mentoring guidance…" /><Button onClick={() => notify("Private project notes saved locally.")}>Save private notes</Button></Panel></div></div></Panel></div>}<DocumentModal title={task.file?.title} open={file} onClose={() => setFile(false)} /><CreationModal title="Add project task" open={create} onClose={() => setCreate(false)} onCreate={(title) => { const result = commit(command, notify, "task.create", { projectId, title }, "Project task created and assigned to an active project member."); if (!result.ok) return false; setSelectedId(result.value.id); setFilter("All tasks"); setTab("Tasks & Reviews"); router.replace(`/dashboard/careers/projects/${projectId}/tasks/${result.value.id}`, { scroll: false }); return true; }} /><Modal title="Record sample submission" open={submitOpen} onClose={() => setSubmitOpen(false)}><form className="workspace-stack" onSubmit={(event) => { event.preventDefault(); const result = commit(command, notify, "task.submit", { projectId, taskId: task.id, notes: submissionNotes.trim(), ...(workLink.trim() ? { workLink: workLink.trim() } : {}) }, "Sample submission recorded and moved to review."); if (!result.ok) { setSubmissionError(result.error); return; } setSubmitOpen(false); setSubmissionNotes(""); setWorkLink(""); setSubmissionError(""); setFeedback(""); setError(""); setFilter("All tasks"); }}><p className="workspace-muted workspace-small">Record sample work in this local dashboard so the submission can be reviewed. No external upload or message is sent.</p><Field label="Submission notes *"><Textarea required rows={5} value={submissionNotes} onChange={(event) => setSubmissionNotes(event.target.value)} placeholder="Describe the completed work and changes in this version…" /></Field><Field label="Work link (optional)"><Input type="url" value={workLink} onChange={(event) => setWorkLink(event.target.value)} placeholder="https://example.com/sample-work" /></Field>{submissionError && <p className={styles.error} role="alert">{submissionError}</p>}<div className="workspace-row"><Button type="button" onClick={() => setSubmitOpen(false)}>Cancel</Button><Button type="submit" variant="primary" disabled={!submissionNotes.trim()}>Record submission</Button></div></form></Modal></>;
}

function CertificatePreview({ item }) { const { db } = useAdmin(); return <div className={styles.certificate}><CompanyLogo className="workspace-certificate-company-logo" /><p>{db.datasets["olentra-admin-company-settings-v1"]?.company}</p><div className={styles.goldLine} /><h3>Certificate of completion</h3><p>This is to certify that</p><h4>Intern {item.id}</h4><p>has completed the sample<br /><strong>{item.track} Internship</strong></p><div className={styles.goldLine} /><p>Completion date: {item.date}<br />Certificate serial: {item.serial}</p><small>{item.status.toUpperCase()} · SAMPLE CERTIFICATE · LOCAL DASHBOARD DEMONSTRATION</small></div>; }
export function CertificatesPage() {
  const { notify, command, db } = useAdmin(); const [rows, setRows] = useLocalState("olentra-admin-certificates", seed("olentra-admin-certificates")); const [tab, setTab] = useState("Eligible"); const [query, setQuery] = useState(""); const [selected, setSelected] = useState(rows[0]?.id || ""); const [generate, setGenerate] = useState(false); const [candidate, setCandidate] = useState(""); const [revoke, setRevoke] = useState(false); const [reason, setReason] = useState(""); const eligible = (db.datasets["olentra-admin-interns"] || []).filter((intern) => intern.status === "Completed" && selectInternProgress(db, intern.id).complete); const available = eligible.filter((intern) => !rows.some((row) => (row.internId || row.id) === intern.id && row.status === "Issued")); const candidates = [...rows, ...eligible.filter((intern) => !rows.some((row) => (row.internId || row.id) === intern.id)).map((intern) => ({id:intern.id,internId:intern.id,track:intern.track,date:intern.completedAt,eligibility:"Approved",status:"Ready",serial:`OL-2026-${intern.id}`}))]; const item = candidates.find((x) => x.id === selected) || candidates[0]; const chosenCandidate = candidate || available[0]?.id || ""; const visible = candidates.filter((x) => contains(x, query) && (tab === "Eligible" ? eligible.some((intern) => intern.id === (x.internId || x.id)) && x.status !== "Revoked" : tab === "Issued" ? x.status === "Issued" : x.status === "Revoked"));
  if (!item) return <><PageHeader title="Certificates" description="Complete and approve required internship tasks before issuing a certificate." /><Panel title="No eligible interns"><Button href="/dashboard/careers/interns">Review internship progress</Button></Panel></>;
  const printCertificate = () => { setTimeout(() => window.print(), 20); };
  return <><PageHeader title="Certificates" description="Issue, view and manage internship completion certificates." actions={<Button variant="primary" icon={Plus} onClick={() => setGenerate(true)}>Generate certificate</Button>} /><Tabs items={["Eligible", "Issued", "Revoked"]} value={tab} onChange={setTab} /><div className="workspace-grid workspace-grid-2"><Panel><SearchInput value={query} onChange={setQuery} placeholder="Search by intern ID, track or certificate ID…" /><DataTable columns={[{ key: "id", label: "Intern ID", render: (v) => <Button variant="ghost" onClick={() => setSelected(v)}>Intern {v}</Button> }, { key: "track", label: "Track" }, { key: "date", label: "Completion date" }, { key: "eligibility", label: "Eligibility", render: (v) => <Status value={v} /> }, { key: "status", label: "Issuance status", render: (v) => <Status value={v} /> }, { key: "actions", label: "Actions", render: (_, row) => <Button icon={Eye} onClick={() => setSelected(row.id)}>Preview</Button> }]} rows={visible} /></Panel><Panel title="Certificate preview" actions={<span className="workspace-small workspace-muted">{item.serial}</span>}><CertificatePreview item={item} /><div className="workspace-grid workspace-grid-2"><Info label="Verification status"><Status value={item.status === "Revoked" ? "Revoked" : item.status === "Ready" ? "Not issued" : "Valid"} /></Info><Info label="Eligibility summary">Required tasks approved</Info></div><div className={styles.certificateActions}><Button variant="primary" icon={Download} onClick={printCertificate}>Print / Save PDF</Button><Button disabled={item.status !== "Issued"} onClick={() => { commit(command, notify, "certificate.publish", { id: item.id }, "Certificate published to the local portal record. No external message sent."); }}>{item.portalPublished ? "Published to portal" : "Publish to portal"}</Button><Button variant="danger" disabled={item.status !== "Issued"} onClick={() => setRevoke(true)}>Revoke</Button></div><p className={styles.footerNote}>Sample certificates only. Print opens the browser’s print dialog, where you can save a PDF.</p></Panel></div><Modal open={generate} onClose={() => setGenerate(false)} title="Generate sample certificate"><div className="workspace-stack"><p className="workspace-muted">Choose an eligible completed intern from the local sample directory.</p><Field label="Eligible intern"><Select value={chosenCandidate} options={available.map((x) => ({ value: x.id, label: `Intern ${x.id} · ${x.track}` }))} onChange={(e) => setCandidate(e.target.value)} /></Field><Button variant="primary" disabled={!available.some((x) => x.id === chosenCandidate)} onClick={() => { const result = commit(command, notify, "certificate.issue", { internId: chosenCandidate }, "Certificate issued in the local directory."); if (result.ok) { setSelected(chosenCandidate); setTab("Issued"); setGenerate(false); } }}>Generate preview certificate</Button></div></Modal><Modal open={revoke} onClose={() => setRevoke(false)} title="Revoke sample certificate"><div className="workspace-stack"><p className="workspace-muted">This changes the local certificate’s verification state to revoked.</p><Field label="Revocation reason"><Textarea value={reason} onChange={(e) => setReason(e.target.value)} /></Field><Button variant="danger" disabled={!reason.trim()} onClick={() => { const result = commit(command, notify, "certificate.revoke", { id: item.id, reason }, "Certificate revoked."); if (result.ok) { setRevoke(false); setReason(""); } }}>Confirm revocation</Button></div></Modal></>;
}

export function InternProfilePage({ internId = "024" }) {
  const { notify, command, db } = useAdmin(); const [interns, setInterns] = useLocalState("olentra-admin-interns", seed("olentra-admin-interns")); const intern = interns.find((x) => x.id === internId); const [tab, setTab] = useState("Overview"); const [checks, setChecks] = useLocalState(`olentra-admin-intern-checks-${internId}`, seed(`olentra-admin-intern-checks-${internId}`)); const [completion, setCompletion] = useLocalState(`olentra-admin-intern-completion-${internId}`, seed(`olentra-admin-intern-completion-${internId}`)); const [access, setAccess] = useLocalState(`olentra-admin-intern-access-${internId}`, seed(`olentra-admin-intern-access-${internId}`)); const [message, setMessage] = useState(false); const [messageText, setMessageText] = useState(""); const [messages, setMessages] = useLocalState(`olentra-admin-intern-messages-${internId}`, seed(`olentra-admin-intern-messages-${internId}`)); const [changeStatus, setChangeStatus] = useState(false); const [nextStatus, setNextStatus] = useState(intern?.status || "");
  if (!intern) return <Missing title="Intern" href="/dashboard/careers/interns" />;
  const assignedTasks = internTasks(db, internId); const internProgress = selectInternProgress(db, internId); const requiredTasks = assignedTasks.filter((row) => row.required !== false); const tasksApproved = requiredTasks.length > 0 && requiredTasks.every((row) => row.status === "Approved"); const completionReady = tasksApproved && completion.slice(1).every(Boolean); const projectRecords = (db.datasets["olentra-admin-projects"] || []).filter((row) => intern.projectIds.includes(row.id));
  const onboarding = <Panel title="Onboarding checklist" actions={<span className="workspace-small workspace-muted">{checks.filter(Boolean).length} of 5 completed</span>}><Progress value={checks.filter(Boolean).length / 5 * 100} />{reference.onboardingLabels.map((label, i) => <label className={styles.checkRow} key={label}><input type="checkbox" checked={checks[i]} onChange={(e) => setChecks(checks.map((x, index) => index === i ? e.target.checked : x))} />{label}</label>)}</Panel>;
  const project = <Panel title="Project progress" actions={<span className="workspace-small workspace-muted">{internProgress.approved.length} of {internProgress.required.length} required tasks</span>}><Progress value={internProgress.progress} />{projectRecords.map((record) => {const rows=assignedTasks.filter((row) => row.projectId === record.id); return <div key={record.id}><div className={styles.cardTitle}><Code2 size={22} /><div><strong>{record.title}</strong><p className="workspace-small workspace-muted">{record.description}</p></div></div><div className={styles.miniGrid}><div><strong>{rows.filter((row) => row.status === "Approved").length}</strong><span>Completed</span></div><div><strong>{rows.filter((row) => row.status === "In progress").length}</strong><span>In progress</span></div><div><strong>{rows.filter((row) => row.status === "In review").length}</strong><span>In review</span></div></div>{rows.length > 0 && <div className={styles.footerActions}><Button href={`/dashboard/careers/projects/${record.id}/tasks/${rows[0].id}`}>View project <ArrowRight size={15} /></Button></div>}</div>;})}</Panel>;
  const submissions = <Panel title="Recent submissions"><DataTable columns={[{key:"title",label:"Submission"},{key:"submitted",label:"Submitted"},{key:"status",label:"Status",render:(value) => <Status value={value} />},{key:"actions",label:"Action",render:(_,row) => <Button href={`/dashboard/careers/projects/${row.projectId}/tasks/${row.id}`} variant="ghost">Review</Button>}]} rows={assignedTasks.filter((row) => row.submitted)} /></Panel>;
  const activity = <Panel title="Activity (administrative)"><DataTable columns={[{key:"date",label:"Date"},{key:"action",label:"Action"},{key:"detail",label:"Details"},{key:"role",label:"By (role)"}]} rows={intern.activity || []} />{messages.map((text,index) => <div key={index} className={styles.feed}><strong>Local portal message draft</strong><p>{typeof text === "string" ? text : text.text}</p></div>)}</Panel>;
  return <><PageHeader eyebrow="Internships / Interns" title={`Intern ${internId}`} description={<span className="workspace-row"><Status value={intern.status} /><span>Internship · {intern.track}</span></span>} actions={<><Button icon={MessageSquare} onClick={() => setMessage(true)}>Message</Button><Button variant="primary" onClick={() => { setNextStatus(intern.status); setChangeStatus(true); }}>Update status</Button></>} /><Panel><div className={styles.profileSummary}>{reference.profileSummary.map(({label,key}) => <div key={key}><span>{label}</span><strong>{intern[key]}</strong></div>)}</div></Panel><Tabs items={["Overview", "Onboarding", "Projects", "Submissions", "Certificates", "Activity"]} value={tab} onChange={setTab} />{tab === "Overview" ? <><div className="workspace-grid workspace-grid-3">{onboarding}{project}<Panel title="Internship lifecycle"><div className={styles.timeline}>{(intern.activity || []).map((event,index) => <div key={event.id || index}><CheckCircle2 size={19} color="#18d79e" /><div><strong>{event.action}</strong><p>{event.date}</p></div></div>)}</div></Panel></div><div className="workspace-grid workspace-grid-3">{submissions}<Panel title="Completion requirements">{reference.completionLabels.map((label, i) => <label key={label} className={styles.checkRow}><input type="checkbox" checked={i === 0 ? tasksApproved : completion[i]} disabled={i === 0} onChange={(e) => setCompletion(completion.map((x, index) => index === i ? e.target.checked : x))} />{label}</label>)}<p className={styles.formNote}>All requirements must be confirmed before marking this internship completed.</p></Panel><Panel title="Access"><Switch label="Intern portal enabled" description="Intern can access their portal, tasks and submissions" checked={access} onChange={(value) => { setAccess(value); notify("Intern portal access updated locally."); }} /><hr className={styles.rule} /><h3 className={styles.subHeading}>Program visibility</h3><p className="workspace-muted workspace-small">Public program visibility is managed separately from this intern’s access.</p><Button href={`/dashboard/careers/programs/${intern.programId}/edit`}>Manage program visibility</Button></Panel></div>{activity}</> : tab === "Onboarding" ? onboarding : tab === "Projects" ? project : tab === "Submissions" ? submissions : tab === "Certificates" ? <Panel title="Intern certificates"><p className="workspace-muted">Certificates are issued after all completion requirements are approved.</p><Button href="/dashboard/careers/certificates">Open certificate management</Button></Panel> : activity}<Modal open={message} onClose={() => setMessage(false)} title={`Message Intern ${internId}`}><div className="workspace-stack"><p className="workspace-muted">Save a local portal message draft. No email or external message will be sent.</p><Textarea rows={5} value={messageText} onChange={(e) => setMessageText(e.target.value)} placeholder="Write a message…" /><Button disabled={!messageText.trim()} variant="primary" onClick={() => { setMessages([...messages, messageText.trim()]); setMessageText(""); setMessage(false); notify("Portal message draft saved locally."); }}>Save message draft</Button></div></Modal><Modal open={changeStatus} onClose={() => setChangeStatus(false)} title="Update internship status"><div className="workspace-stack"><Field label="Status"><Select options={["Onboarding", "Active", "Completed", "Dropped"]} value={nextStatus} onChange={(e) => setNextStatus(e.target.value)} /></Field>{nextStatus === "Completed" && !completionReady && <p className={styles.error}>Approve every required task and confirm the final review and closure in the overview first.</p>}<Button variant="primary" disabled={nextStatus === "Completed" && !completionReady} onClick={() => { const result = commit(command, notify, "intern.transition", { id: internId, status: nextStatus }, "Intern lifecycle status updated."); if (result.ok) setChangeStatus(false); }}>Save status</Button></div></Modal></>;
}

export function ProgramEditorPage({ programId = "frontend" }) {
  const { notify, command, db } = useAdmin(); const [opportunities, setOpportunities] = useLocalState("olentra-admin-opportunities", seed("olentra-admin-opportunities")); const opportunity = opportunities.find((x) => x.id === programId); const [tab, setTab] = useState("Details"); const [model, setModel] = useLocalState(`olentra-admin-program-${programId}`, seed(`olentra-admin-program-${programId}`)); const [preview, setPreview] = useState(false); const [error, setError] = useState("");
  if (!opportunity) return <Missing title="Program" href="/dashboard/careers" />;
  const change = (key, value) => setModel({ ...model, [key]: value }); const save = (status) => { const result = commit(command, notify, "program.save", { id: programId, model, status }, status === "In review" ? "Program submitted for review." : "Program draft saved."); setError(result.ok ? "" : result.error); };
  const form = <div className={styles.fieldList}>{reference.programFormLabels.map((label, i) => <label key={label}><span>{label}</span><span className="workspace-row"><span className="workspace-muted workspace-small">Required</span><input type="checkbox" aria-label={`${label} required`} checked={model.form[i]} onChange={(e) => change("form", model.form.map((x, index) => index === i ? e.target.checked : x))} /></span></label>)}</div>;
  return <><PageHeader eyebrow={`Internships / Programs / ${opportunity.title}`} title="Edit internship program" description={<Status value={model.status} />} actions={<><Button onClick={() => save("Draft")}>Save draft</Button><Button icon={Eye} onClick={() => setPreview(true)}>Preview</Button><Button variant="primary" onClick={() => save("In review")}>Request review</Button></>} /><Tabs items={["Details", "Eligibility", "Application form", "Schedule", "Visibility"]} value={tab} onChange={setTab} />{error && <p className={styles.error} role="alert">{error}</p>}<div className={styles.programLayout}><Panel>{tab === "Details" && <div className="workspace-stack"><Field label="Title *"><Input value={model.title} onChange={(e) => change("title", e.target.value)} /></Field><div className="workspace-grid workspace-grid-3"><Field label="Track *"><Select options={["Engineering", "AI research", "Design", "Product management"]} value={model.track} onChange={(e) => change("track", e.target.value)} /></Field><Field label="Work mode *"><Select options={["Remote", "Hybrid", "On-site"]} value={model.mode} onChange={(e) => change("mode", e.target.value)} /></Field><Field label="Duration *"><Select options={["8 weeks", "12 weeks", "16 weeks", "24 weeks"]} value={model.duration} onChange={(e) => change("duration", e.target.value)} /></Field></div><Field label="Description *"><div className={styles.richToolbar}>Paragraph　 |　 <b>B</b>　<i>I</i>　<u>U</u>　 • List</div><Textarea rows={6} value={model.description} onChange={(e) => change("description", e.target.value)} /></Field><Field label="Skills *" hint="Separate skills with commas"><Input value={model.skills} onChange={(e) => change("skills", e.target.value)} /></Field><div className={styles.formSection}><div className="workspace-between workspace-row"><h3>Application form fields (preview)</h3><Button icon={Pencil} onClick={() => setTab("Application form")}>Edit form</Button></div><p className="workspace-small workspace-muted">These are the fields applicants see for this program.</p>{form}</div></div>}{tab === "Eligibility" && <div className="workspace-stack"><h3>Eligibility requirements</h3><Field label="Who can apply?"><Textarea rows={7} value={model.eligibility} onChange={(e) => change("eligibility", e.target.value)} /></Field><Field label="Required skills"><Input value={model.skills} onChange={(e) => change("skills", e.target.value)} /></Field></div>}{tab === "Application form" && <><h3>Application form configuration</h3><p className="workspace-muted">Choose which fields are required. Portfolio remains optional by default.</p>{form}</>}{tab === "Schedule" && <div className="workspace-stack"><h3>Intake schedule</h3><Field label="Opens on"><Input type="date" value={model.opens} onChange={(e) => change("opens", e.target.value)} /></Field><Field label="Closes on"><Input type="date" min={model.opens} value={model.closes} onChange={(e) => change("closes", e.target.value)} /></Field><p className={styles.formNote}>Dates are interpreted in the selected program timezone. This demo records the schedule locally.</p></div>}{tab === "Visibility" && <div className="workspace-stack"><h3>Visitor experience</h3><Switch label="Public visibility" description="Show program on the public careers page" checked={model.public} onChange={(v) => change("public", v)} /><Switch label="Accept applications" description="Allow new submissions for this program" checked={model.applications} onChange={(v) => change("applications", v)} /><Switch label="Existing intern portal" description="Current interns can access program resources" checked={model.portal} onChange={(v) => change("portal", v)} /><div className={styles.noteBanner}>Publishing program content and opening applications are separate actions.</div></div>}<p className={styles.footerNote}>Publishing program content and opening applications are separate actions.</p></Panel><div className="workspace-stack"><Panel title="Intake"><div className="workspace-stack"><Field label="Opens on"><Input type="date" value={model.opens} onChange={(e) => change("opens", e.target.value)} /></Field><Field label="Closes on"><Input type="date" min={model.opens} value={model.closes} onChange={(e) => change("closes", e.target.value)} /></Field><Field label="Timezone"><Select options={["Asia/Kolkata", "UTC", "America/New_York", "Europe/London"]} value={model.timezone} onChange={(e) => change("timezone", e.target.value)} /></Field><Field label="Capacity"><Input type="number" min="1" max="1000" value={model.capacity} onChange={(e) => change("capacity", Math.max(1, Number(e.target.value)))} /></Field><Field label="Regions"><Select options={["Global", "Asia Pacific", "Europe", "Americas"]} value={model.regions} onChange={(e) => change("regions", e.target.value)} /></Field></div></Panel><Panel title="Publication"><Info label="Publication status"><Status value={model.status} /></Info><div className={styles.switchBlock}><Switch label="Public visibility" description="Show program on the public careers page" checked={model.public} onChange={(v) => change("public", v)} /></div><div className={styles.switchBlock}><Switch label="Accept applications" description="Allow new program submissions" checked={model.applications} onChange={(v) => change("applications", v)} /></div><div className={styles.switchBlock}><Switch label="Existing intern portal" description="Current interns can access resources" checked={model.portal} onChange={(v) => change("portal", v)} /></div></Panel></div></div><Modal open={preview} onClose={() => setPreview(false)} title="Program visitor preview"><div className={styles.programmePreview}><Badge tone={model.applications ? "success" : "muted"}>{model.applications ? "Applications open" : "Applications closed"}</Badge><h2>{model.title}</h2><p>{model.description}</p><div className={styles.skills}>{model.skills.split(",").filter(Boolean).map((skill) => <Badge key={skill} tone="blue">{skill.trim()}</Badge>)}</div><footer><span>{model.mode}</span><span>{model.duration}</span><span>{model.regions}</span></footer><p className={styles.formNote}>{model.public ? "Public page visible" : "Private preview · Public page hidden"}</p></div></Modal></>;
}
